import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {verifyGpDirectoryActivation,gpDirectoryActivationHistoricalView,gpActivationAuthenticatedRead,gpActivationAuthenticatedContent,gpActivationAuthenticatedDiff,gpActivationAuthenticatedAncestor,gpActivationReaderProvenance} from '../release/gp-directory-activation-20261015.mjs';
import {verifyGpCodeStack,gpMemberCodeHistoricalView} from '../release/gp-member-code-admission-20261014.mjs';
import {GP_ACTIVATION_PATHS,disableGpDirectoryConfiguration,GP_ACTIVATION_ORIGINAL_BLOBS,GP_ACTIVATION_AUTHORITY,gpActivationBindingsSha256} from '../release/gp-directory-activation-contract-20261015.mjs';
import {originalGpActivationBridge} from '../release/gp-directory-activation-source-20261015.mjs';
import {assertActivatedGpHqProviderSnapshot} from '../release/gp-directory-activation-provider-20261015.mjs';
import {assertHqProviderSnapshot} from '../release/gp-hq-preservation-successor-20261015.mjs';
const git=(...a)=>execFileSync('/usr/bin/git',['--no-replace-objects',...a],{encoding:'utf8',maxBuffer:64e6}),head=git('rev-parse','HEAD').trim(),content=(r,p)=>git('show',r+':'+p),blob=(r,p)=>git('rev-parse',r+':'+p).trim(),diff=(a,b)=>git('diff','--no-renames','--name-only',a,b).trim().split('\n').filter(Boolean),ancestor=(a,b)=>git('merge-base','--is-ancestor',a,b),record=JSON.parse(content(head,'release/approved-runtime-composition.json')),c=record.gpDirectoryActivation20261015;
test('exact flags-ON head projects through actual accepted GP-code OFF proof',()=>{verifyGpDirectoryActivation(c);verifyGpCodeStack(record.gpMemberCode20261014);const activation=gpDirectoryActivationHistoricalView(),gp=gpMemberCodeHistoricalView();assert.equal(activation.rawHead,head);assert.equal(activation.head,c.base);const prior=JSON.parse(content(c.base,'release/approved-runtime-composition.json'));assert.deepEqual(activation.record,prior);assert.equal(gp.rawHead,head);assert.equal(gp.head,prior.gpMemberCode20261014.base);assert.deepEqual(gp.record,JSON.parse(content(gp.head,'release/approved-runtime-composition.json')));});
test('the three physical configurations inverse exactly, including the core/coaching mirror',()=>{assert.equal(content(head,'wrangler.jsonc'),content(head,'wrangler.coaching.jsonc'));for(const p of GP_ACTIVATION_PATHS)assert.equal(disableGpDirectoryConfiguration(p,content(head,p)),content(c.base,p));for(const[p,pins]of Object.entries(GP_ACTIVATION_ORIGINAL_BLOBS)){assert.equal(blob(GP_ACTIVATION_AUTHORITY.originalSource,p),pins.after);assert.equal(blob(GP_ACTIVATION_AUTHORITY.originalSource+'^',p),pins.before);}});
test('every literal flags-OFF GP assertion is retained as a real immutable accepted witness',()=>assert.equal(originalGpActivationBridge(content(head,'release/gp-member-code-admission-20261014.mjs')),content(c.base,'release/gp-member-code-admission-20261014.mjs')));
test('base/provider adoption, broad authority, email and reimport cannot broaden',()=>{for(const changed of[{...c,base:'f'.repeat(40)},{...c,emailAuthority:true},{...c,genericAdoptionAllowed:true},{...c,productionDataWrites:1},{...c,reimport:true},{...c,predecessor:{...c.predecessor,source:'e'.repeat(40)}}])assert.throws(()=>verifyGpDirectoryActivation(changed),/literal GP directory activation/);});
for(const p of['release','wrangler.jsonc','wrangler.hq-management.jsonc'])test('equal invented activated raw aliases cannot disappear: '+p,()=>{const v=gpDirectoryActivationHistoricalView(),supplied=(r,path)=>(r==='HEAD'||r===head)&&path===p?'invented identical raw source':blob(r,path);assert.throws(()=>gpActivationAuthenticatedRead(supplied,v)('HEAD',p),/Unauthentic supplied source/);});
test('projected source, content, diff, ancestry and freshness stay authenticated',()=>{const v=gpDirectoryActivationHistoricalView(),p='wrangler.jsonc';let poisoned=false;const read=gpActivationAuthenticatedRead((r,path)=>poisoned&&r===c.base?'invented G':blob(r,path),v);read('HEAD',p);poisoned=true;assert.throws(()=>read('HEAD',p),/Unauthentic supplied source/);assert.throws(()=>gpActivationAuthenticatedContent((r,path)=>r===c.base?'forged G content':content(r,path),v)('HEAD',p),/Unauthentic supplied content/);assert.throws(()=>gpActivationAuthenticatedDiff((a,b)=>b===c.base?[]:diff(a,b),v)(record.gpMemberCode20261014.base,'HEAD'),/Supplied diff/);assert.throws(()=>gpActivationAuthenticatedAncestor((a,b)=>b===c.base?false:ancestor(a,b),v)(record.gpMemberCode20261014.base,'HEAD'),/Supplied ancestry/);assert.equal(gpActivationReaderProvenance(v.read).view,v);assert.equal(gpActivationReaderProvenance(()=>{}),null);assert.throws(()=>gpActivationAuthenticatedRead(blob,{...v})('HEAD',p),/Independently admitted/);});
test('defaultReader cannot waive a supplied raw activation source callback',()=>{const v=gpDirectoryActivationHistoricalView((r,p)=>r==='HEAD'?'forged despite defaultReader':blob(r,p),{defaultReader:true});assert.throws(()=>v.read('HEAD','release'),/Unauthentic supplied source/);});
test('F to G to prior source adapters authenticate the same literal fourth native ref',()=>{const activation=gpDirectoryActivationHistoricalView(),gp=gpMemberCodeHistoricalView(),prior=record.gpMemberCode20261014.base;for(const view of[activation,gp])for(const ref of[c.base,prior])for(const p of['wrangler.jsonc','release']){const genuine=blob(ref,p),genuineContent=content(ref,p);assert.equal(view.authentic(genuine,'HEAD',p,ref),true,'Genuine explicitly pinned prior blob must be admitted');assert.equal(view.authentic(genuineContent,'HEAD',p,ref),true,'Genuine explicitly pinned prior native content must be admitted');assert.equal(view.authentic('forged equal prior callback','HEAD',p,ref),false);assert.equal(view.authentic('forged equal prior callback',ref,p,ref),false);assert.equal(view.nativeAuthentic(genuine,ref,p),true);assert.equal(view.nativeAuthentic('forged prior source',ref,p),false);}assert.notEqual(blob(head,'wrangler.jsonc'),blob(c.base,'wrangler.jsonc'));assert.equal(activation.authentic(blob(c.base,'wrangler.jsonc'),'HEAD','wrangler.jsonc'),false,'Default raw F authentication must not silently substitute G');assert.equal(activation.authentic(blob(head,'wrangler.jsonc'),'HEAD','wrangler.jsonc',c.base),false,'A native F blob cannot satisfy an explicit G reference');});
test('an explicit projected HEAD cannot be passed as the current raw source',()=>assert.throws(()=>verifyGpCodeStack(record.gpMemberCode20261014,{head:c.base}),/Actual raw activated HEAD/));
test('the new provider boundary cannot weaken the original exact-version, bundle or partner kernel',()=>{const bundle=Buffer.from('fictional activation regression, not live evidence'),expected={deployment:'owned',version:'owned-version',bytes:bundle.length,sha256:__FIXTURE_SHA__},snapshot={deployment:{id:'owned',versions:[{version_id:'owned-version',percentage:100}]},version:{id:'owned-version',resources:{bindings:[{name:'HQ_PARTNERS_ENABLED',type:'plain_text',text:'true'},{name:'MEMBER_GP_DIRECTORY_V2_ENABLED',type:'plain_text',text:'true'}]}},bundle};expected.otherBindingsSha256=gpActivationBindingsSha256(snapshot.version.resources.bindings);const before=JSON.stringify(snapshot.version);assert.equal(assertActivatedGpHqProviderSnapshot(snapshot,expected,assertHqProviderSnapshot).gpEnabled,true);assert.equal(JSON.stringify(snapshot.version),before);for(const scenario of['partner','bundle','traffic','opaque','false','duplicate']){const s={...snapshot,deployment:structuredClone(snapshot.deployment),version:structuredClone(snapshot.version),bundle};if(scenario==='partner')s.version.resources.bindings[0].text='false';if(scenario==='bundle')s.bundle=Buffer.from('x'.repeat(bundle.length));if(scenario==='traffic')s.deployment.versions[0].percentage=50;if(scenario==='opaque')s.version.resources.bindings[1].type='secret_text';if(scenario==='false')s.version.resources.bindings[1].text='false';if(scenario==='duplicate')s.version.resources.bindings.push({...s.version.resources.bindings[1]});assert.throws(()=>assertActivatedGpHqProviderSnapshot(s,expected,assertHqProviderSnapshot));}});
